    explanation: "相対性理論は、日常語の「すべては相対的で真実はない」という意味ではありません。むしろ、どの観測者にも共通して成り立つ法則を探した理論です。特殊相対性理論では、光の速さは観測者の運動状態にかかわらず一定であるという出発点から、時間や空間についての常識が変わります。高速で動く物体では時間の進み方が遅れ、長さも縮んで測られる。これは感覚的には奇妙ですが、粒子加速器や精密時計で確認されています。さらに有名な E=mc² は、質量とエネルギーが深く結びつくことを示します。一般相対性理論では、重力を物体同士が引っぱる力としてだけでなく、質量やエネルギーによって時空が曲がり、その曲がった時空に沿って物体が動くと説明します。太陽の近くで光が曲がること、水星の近日点移動、ブラックホール、重力波などはこの理論と関係します。GPSも、地上と衛星で時間の進み方がわずかに違うため、相対論的補正が必要です。アインシュタインはニュートン力学を単純に捨てたのではなく、低速で重力が弱い範囲ではニュートン力学が近似として成り立つことも示しました。相対性理論は、常識を壊しながら、より広い秩序を見せた理論です。",
