    explanation: "ユークリッドの『原論』は、数学史上もっとも影響力の大きい本の一つです。そこでは、図形に関する知識がばらばらに並べられるのではなく、定義、公準、公理、命題、証明という形で体系化されます。点とは何か、線とは何か、円とは何かを定め、少数の前提から多くの定理を導く。この形式は、数学とは単に計算することではなく、前提から論理的に結論を導く営みであることを示しました。たとえば三角形の性質や平行線の性質は、図を見て何となく正しそうだからではなく、証明によって確かめられます。『原論』は古代ギリシア数学の集大成であり、近代に至るまで長く教科書として使われました。第五公準、つまり平行線公準をめぐる疑問は、後に非ユークリッド幾何学を生むきっかけにもなります。これは、当たり前に見える空間の性質さえ、前提を変えれば別の数学体系が成り立つことを示しました。ユークリッドの重要性は、個々の定理だけでなく、知識をどのように厳密に組み立てるかという方法を示した点にあります。数学的証明の文化を理解する入口になる著作です。",
