    explanation: "ゲーデルの不完全性定理は、二十世紀の数学観を大きく変えた結果です。数学を完全に公理化し、すべての真理を機械的に証明できる体系にしたいという夢がありました。ヒルベルトのプログラムは、その代表です。ゲーデルは、自然数の算術を表せるほど十分に強く、矛盾のない形式体系では、その体系の中で証明も反証もできない命題が存在することを示しました。さらに、その体系自身の無矛盾性を、同じ体系の中だけで証明することにも限界があると示しました。大まかに言えば、「この文はこの体系内では証明できない」という自己言及的な構造を、数学的に精密化したのです。これは、数学がいい加減だという意味ではありません。むしろ形式化を徹底したからこそ、形式体系の限界が明らかになりました。通俗的には「人間の理性には限界がある」「AIには不可能なことがある」と広く使われますが、そうした応用には慎重さが必要です。本来は、形式体系、証明可能性、算術、無矛盾性に関する厳密な定理です。それでも、どんなルール体系も万能ではないという衝撃は大きく、数学、論理学、計算機科学、哲学に深い影響を与えました。",
