    explanation: "囚人のジレンマは、個人にとって合理的な選択が、全体としては悪い結果を生むことを示す有名なモデルです。二人の容疑者が別々に取り調べを受け、互いに黙秘するか自白するかを選ぶとします。二人とも黙秘すれば軽い刑ですみます。しかし相手が黙秘して自分だけ自白すれば、自分は得をして相手は重い刑になります。逆に相手だけが自白すれば自分が損をします。そのため、相手を信用できない状況では、自分も自白する方が安全に見えます。結果として二人とも自白し、二人とも黙秘した場合より悪い結果になります。これは犯罪の話に限りません。軍拡競争、価格競争、環境問題、共有資源の利用、職場での過剰労働などにも似た構造があります。全員が協力すればよいと分かっていても、裏切られる不安があると協力は壊れます。一方で、同じ相手と何度も関わる反復ゲームでは、信頼、評判、報復、制度が協力を支えることがあります。囚人のジレンマは、人間が利己的だから悪いという単純な話ではなく、情報、信頼、ルールの設計が行動を変えることを教えます。",
