    explanation: "マタイ効果は、すでに多く持つ者がさらに多くを得るという累積的な格差の仕組みを表す言葉です。名称は新約聖書のマタイ福音書の一節に由来しますが、社会学者マートンは科学の世界を分析するために用いました。たとえば同じ研究成果でも、無名の若手より有名な研究者の方が注目され、引用され、評価されやすい。評価が集まると研究費や共同研究の機会も増え、さらに成果を出しやすくなります。これは本人の能力だけの問題ではなく、評判が評判を呼ぶ構造です。教育でも、幼い頃に読書習慣や学習支援を得た子はさらに学びやすくなり、遅れた子はますます差を広げられやすい。SNSでも、フォロワーが多い人の投稿ほどさらに拡散されます。マタイ効果は、成功や失敗を個人の努力だけで説明する見方にブレーキをかけます。初期条件、制度、評価の仕組みが、その後の機会を大きく左右するからです。一方で、格差が累積するなら、早期支援や透明な評価、機会の再配分が重要になります。競争社会の中で「実力」と見えるものが、どれだけ構造に支えられているのかを考えるための概念です。",
