    explanation: "法の支配は、近代立憲主義を理解するための基本概念です。重要なのは、単に法律がたくさんあるという意味ではないことです。独裁国家にも法律はあります。問題は、その法律が権力者の気分や都合で変えられず、誰に対しても一般的に適用され、政府自身も法に従うかどうかです。法の支配では、逮捕や処罰には根拠が必要で、裁判所は独立し、人々は事前にルールを知ることができなければなりません。これに対して、人の支配では、王、党、指導者、役人の判断が法より上に置かれます。イギリスのマグナ・カルタや権利章典、近代憲法の発展は、権力を法で縛る歴史と関係します。法の支配は自由を守るために必要ですが、同時に法そのものが不公正な場合はどうするかという問題もあります。形式的に法に従っていても、差別的な法律や少数者を排除する制度なら正義とは言えません。そのため、現代では人権保障、適正手続、司法の独立、憲法による権力制限と結びつけて理解されます。法の支配は、政治の安定だけでなく、市民が権力を予測し、批判し、争うための土台です。",
