    explanation: "認知的不協和は、自分の信念、態度、行動の間に矛盾があるときに生じる心理的不快感を指します。人はその不快感を減らすため、事実の見方を変えたり、自分の行動を正当化したりします。フェスティンガーの有名な実験では、退屈な作業をした参加者に、次の人へ「楽しかった」と伝えさせました。高い報酬をもらった人は、嘘をついた理由を報酬で説明できます。しかし低い報酬しかもらわなかった人は、なぜ嘘をついたのか説明しにくいため、実は作業は少し楽しかったのだと態度を変えやすくなりました。日常でも、高い買い物をした後に欠点を見ないようにする、健康に悪いと知りながら喫煙を続けて「ストレス解消だから」と説明する、支持した政治家の失敗を過小評価する、といった場面があります。認知的不協和は、人間が純粋に証拠だけで考える存在ではなく、自分の一貫性を保ちたい存在であることを示します。一方で、不協和は悪いだけではありません。矛盾に気づくことで、行動を改めたり、より深く考えたりするきっかけにもなります。",
