    explanation: "ピグマリオン効果は、周囲の期待が相手の成果に影響を与えることがあるという考えです。名前は、ギリシア神話で自分の作った像に恋し、その像が命を得るピグマリオンに由来します。心理学では、ローゼンタールとジェイコブソンの学校研究が有名です。教師に対して、ある生徒たちは今後伸びる可能性が高いと伝えると、実際には無作為に選ばれた生徒であっても、後に成績が伸びたと報告されました。教師が期待を持つことで、声かけ、待つ時間、難しい課題を与える姿勢、失敗への反応が微妙に変わり、生徒の自己認識や行動にも影響したと考えられます。これは教育だけでなく、職場の育成、スポーツ指導、家庭でも起こりえます。ただし、期待すれば必ず能力が伸びるという魔法ではありません。研究結果の再現性や効果の大きさには議論があり、期待が過剰なプレッシャーになる場合もあります。重要なのは、人は純粋に内面の能力だけで伸びるのではなく、周囲からどう見られ、どう扱われるかに影響されるという点です。ラベル貼りが人を狭めることもあれば、適切な期待が可能性を開くこともあります。",
