    summary: "周囲に人が多いほど、個人が助けに入る可能性が下がることがあるという社会心理学の現象。",
    explanation: "傍観者効果は、緊急事態で周囲に人が多いほど、かえって一人ひとりが行動しにくくなる現象です。ラタネとダーリーは、キティ・ジェノヴィーズ事件の報道を背景に研究を進めました。人が多ければ助けが増えるように思えますが、実際には責任が分散します。自分がやらなくても誰かがやるだろうと思ったり、周囲が動かないなら大したことではないのだろうと解釈したりします。これを責任の分散、状況の曖昧さ、多元的無知などで説明します。たとえば駅で人が倒れていても、周囲が通り過ぎていると、自分も立ち止まるのをためらうことがあります。いじめやハラスメントの場面でも、見ている人が多いのに誰も止めないことがあります。傍観者効果を知ることは、冷たい人が多いと責めるためではなく、行動できない構造を理解するために役立ちます。対策としては、誰かを具体的に指名して助けを求める、自分が最初に動く、緊急事態か迷ったら確認する、といった方法があります。社会的状況は個人の道徳心を強く左右するため、善意だけに頼らない仕組みが重要です。",
