    explanation: "起承転結は、文章や物語の構成を説明する有名な言葉です。起で話題を起こし、承でそれを受けて展開し、転で視点や状況を変え、結でまとめます。学校の作文でもよく教えられますが、もとは漢詩、とくに絶句の構成を説明する型と関係します。たとえば最初に情景を示し、次にその情景を受け、第三句で別の要素を入れて意外な広がりを作り、最後に全体の余韻を結ぶ。ここで面白いのは、転が必ずしも劇的な事件やどんでん返しだけを意味しないことです。少し視点をずらすことで、それまでの内容が別の意味を帯びます。現代ではプレゼンや漫画、ブログ記事にも応用されます。ただし、すべての文章を起承転結に当てはめればよいわけではありません。論文や報告書では、結論を先に示す方が分かりやすいこともあります。西洋的な三幕構成や問題解決型の文章とはリズムが違います。起承転結は、情報を効率よく伝えるだけでなく、読者に余韻や変化を感じさせる構成法として理解すると役立ちます。型を知ることで、型から外す判断もしやすくなります。",
