    summary: "進化を個体や種ではなく、遺伝子の複製成功を中心に説明する視点を広めたドーキンスの著作名。",
    explanation: "『利己的な遺伝子』は、ドーキンスが進化を遺伝子の視点から説明した有名な本です。ここでいう利己的とは、遺伝子に意識や欲望があるという意味ではありません。自然選択の結果として、自分のコピーを残しやすい遺伝子が集団内に広がる、という比喩です。個体は遺伝子が作る乗り物のように説明されることもあります。この視点は、なぜ親が子を守るのか、なぜ血縁者への利他行動が進化しうるのか、なぜ一見自己犠牲的な行動が見られるのかを考える助けになります。たとえば、自分の子や兄弟を助ける行動は、自分と共通する遺伝子の存続に貢献する場合があります。ただし、この概念は非常に誤解されやすい。人間は遺伝子に操られるだけの存在だとか、利己的に生きるのが自然だという倫理的主張ではありません。ドーキンス自身も、遺伝子が利己的だから人間も利己的であるべきだとは言っていません。文化、学習、制度、道徳は人間の行動に大きく関わります。この本は、進化の単位をどう見るかという科学的視点を広めた一方、遺伝子決定論への誤読にも注意が必要です。",
