    explanation: "ノイマン型コンピュータは、プログラム内蔵方式のコンピュータ構成を指す言葉です。現在の多くのコンピュータは、命令であるプログラムと処理対象のデータを同じ記憶装置に置き、CPUが順に読み出して実行します。この方式以前の計算機では、配線を変更したり、外部から命令を与えたりする必要がありました。プログラムを記憶装置に入れ替えられるようになると、同じ機械でさまざまな処理を実行できます。これは、コンピュータが専用機械から汎用機械へ変わる大きな転換でした。フォン・ノイマンの名前で呼ばれますが、アイデアは彼一人だけのものではなく、ENIACやEDVACに関わった多くの研究者の成果が背景にあります。ノイマン型の特徴は便利である一方、CPUと記憶装置の間のデータ移動が性能の制約になるノイマンボトルネックも生みます。現代ではGPU、キャッシュ、並列処理、ニューラルネット用チップなど、さまざまな工夫がこの制約に向き合っています。ノイマン型を知ると、コンピュータが命令とデータを同じ記号として扱うという、情報技術の根本が見えてきます。",
