    explanation: "ジニ係数は、所得や資産の分配がどれだけ不平等かを示す統計指標です。完全に平等なら0、たった一人がすべてを持つ完全不平等なら1に近づきます。ローレンツ曲線という図で考えると分かりやすいです。横軸に人口の累積割合、縦軸に所得の累積割合を取り、全員が同じ所得なら45度線になります。実際には低所得層から順に足していくと、所得の累積はゆっくり増えるため曲線は下にふくらみます。そのふくらみの大きさからジニ係数が計算されます。ジニ係数は、国際比較や時系列比較で格差の大きさを見るのに便利です。ただし一つの数字だけでは、貧困の深刻さ、中間層の厚み、上位層の突出、地域差、税や社会保障の影響までは分かりません。同じジニ係数でも社会の実感が違うことがあります。格差を議論するとき、感情論だけでなく測定指標を持つことは重要ですが、その数字が何を見せ、何を隠すかも同時に見る必要があります。",
