    explanation: "ネットワーク効果は、ある商品やサービスの価値が、利用者の数によって増える現象です。電話は典型例です。電話機を一人だけが持っていても価値は低いですが、多くの人が持つほど連絡できる相手が増え、価値が高まります。SNS、メッセージアプリ、決済サービス、オンライン市場、ゲーム機、ファイル形式などにも同じ構造があります。友人がいるからそのSNSを使う、出品者と買い手が多いからその市場を使う、周囲が使うから同じ文書形式を選ぶ、という循環が生まれます。この効果は便利な標準を作る一方で、先行した企業や規格が強くなりすぎる原因にもなります。多少品質が高い新サービスが出ても、知人や取引先が移らなければ乗り換えにくいからです。ネットワーク効果には、利用者同士が直接つながる直接効果と、売り手と買い手、開発者と利用者のように別グループが互いに価値を高める間接効果があります。現代のプラットフォーム経済を理解するうえで欠かせない概念です。",
