    explanation: "消極的自由は、他者や国家から邪魔されない自由を指します。バーリンは『二つの自由概念』で、自由には少なくとも二つの意味があると整理しました。消極的自由では、問題は「どこまで干渉されずに行動できるか」です。信仰を強制されない、職業選択を妨げられない、言論を検閲されない、家に勝手に入られない、といった自由が典型です。消極的という語は、価値が低いという意味ではありません。むしろ近代自由主義の核心です。国家が善い生き方を一方的に決め、本人のためだとして介入しすぎると、自由は失われます。たとえば健康によい、道徳的によい、社会のためによいという理由で、個人の選択をどこまで制限してよいのかは難しい問題です。一方で、完全に干渉がないだけで自由といえるかも問題になります。貧困や教育不足で選択肢が実質的にない場合、形式的には妨げられていなくても、自由に生きられるとは言いにくいからです。消極的自由は、国家権力への警戒と個人の領域を守る思想として重要です。",
