    explanation: "デフォルト効果は、最初から設定されている選択肢が、そのまま選ばれやすくなる現象です。人はすべての選択を毎回じっくり比較しているわけではありません。変更するのが面倒、失敗したくない、初期設定なら推奨されているのだろうと思う、今の状態を変える理由が弱い、といった理由でデフォルトを受け入れます。臓器提供の意思表示、年金加入、メール配信、アプリのプライバシー設定、保険の特約、サブスクリプションの更新など、初期設定は行動に大きな影響を与えます。ナッジ政策では、この性質を利用して、強制せずに望ましい行動を増やすことが考えられます。一方で、企業が不要なオプションや不利な設定をデフォルトにして利益を得る場合もあります。デフォルトは中立に見えて、実は強い設計上のメッセージです。この概念を知ると、サービスを使うときに、最初からオンになっているものは誰の利益になるのか、自分で選んだつもりの行動が設計に誘導されていないかを確認できます。",
