    explanation: "規模の経済は、生産量や事業規模が大きくなるほど、一単位あたりの費用が下がる現象です。工場を建てる、機械を導入する、研究開発をする、広告を出すといった費用は、少量生産でも大量生産でも一定部分がかかります。大量に作れば、その固定費を多くの商品に分散できるため、平均費用が下がります。自動車、半導体、鉄鋼、製薬、物流、クラウドサービスなどでは、規模の経済が競争力を大きく左右します。大企業が安く大量に供給できる理由の一つです。一方で、規模が大きくなりすぎると、組織が複雑になり、意思決定が遅くなり、管理費用が増える場合もあります。また、規模の経済は参入障壁にもなります。新規企業は最初から大量生産できないため、既存企業の低価格に対抗しにくいからです。自然独占やプラットフォーム支配を考えるときにも重要です。規模の経済を知ると、単に企業努力だけでなく、生産構造そのものが価格や市場集中を作ることが分かります。",
